export const SITE = "https://kuchup.com";
export const OG_IMAGE = `${SITE}/og-default.png`;
export const LOGO = `${SITE}/static/icons/kuchup-bird.png`;

export const ENGINEERING_AUTHOR = {
  name: "Amin Mortezaie",
  url: "https://github.com/AminMortezaie",
} as const;

export type EngineeringPostMeta = {
  slug: string;
  title: string;
  description: string;
  metric: string;
  datePublished: string;
  dateModified: string;
};

export const ENGINEERING_POSTS: readonly EngineeringPostMeta[] = [
  {
    slug: "cant-start-new-thread",
    title: "can't start new thread: 186 companies looked dead",
    description:
      "On 1 September 2026 the production board showed fetch problems on most companies. 357 of 358 recent errors were RuntimeError: can't start new thread. The career sites were fine. The worker had run out of OS threads.",
    metric:
      "186 / 394 companies flagged · 357 / 358 errors were the same RuntimeError",
    datePublished: "2026-09-06",
    dateModified: "2026-09-06",
  },
];

export function engineeringPostPath(slug: string): string {
  return `/engineering/${slug}`;
}

export function getEngineeringPost(
  slug: string,
): EngineeringPostMeta | undefined {
  return ENGINEERING_POSTS.find((post) => post.slug === slug);
}

export function formatPostDate(iso: string): string {
  const [year, month, day] = iso.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
}

import { Footer } from "@/components/Footer";
import { Header } from "@/components/Header";

export function EngineeringShell({ children }: { children: React.ReactNode }) {
  return (
    <div className="min-h-screen">
      <div className="mx-auto max-w-site px-4 pb-8 pt-5 sm:px-5">
        <Header />
        {children}
        <Footer />
      </div>
    </div>
  );
}

import type { Metadata } from "next";
import { EngineeringShell } from "@/components/engineering/EngineeringShell";
import {
  ENGINEERING_POSTS,
  OG_IMAGE,
  SITE,
  engineeringPostPath,
  formatPostDate,
} from "@/lib/engineering-posts";

const TITLE = "Engineering notes from production";
const DESCRIPTION =
  "Measured incidents from the Kuchup fetch worker and job board — real numbers, wrong hypotheses, and the fix.";
const CANONICAL = `${SITE}/engineering`;

export const metadata: Metadata = {
  title: TITLE,
  description: DESCRIPTION,
  alternates: { canonical: "/engineering" },
  openGraph: {
    title: `${TITLE} | Relocation Jobs`,
    description: DESCRIPTION,
    url: CANONICAL,
    siteName: "Relocation Jobs",
    type: "website",
    images: [
      {
        url: OG_IMAGE,
        width: 1200,
        height: 630,
        alt: TITLE,
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    title: `${TITLE} | Relocation Jobs`,
    description: DESCRIPTION,
    images: [OG_IMAGE],
  },
};

export default function EngineeringIndexPage() {
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Blog",
    name: "Kuchup Engineering",
    url: CANONICAL,
    description: DESCRIPTION,
    blogPost: ENGINEERING_POSTS.map((post) => ({
      "@type": "BlogPosting",
      headline: post.title,
      description: post.description,
      datePublished: post.datePublished,
      url: `${SITE}${engineeringPostPath(post.slug)}`,
    })),
  };

  return (
    <EngineeringShell>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <main className="mx-auto mt-12 max-w-2xl">
        <p className="text-sm font-medium uppercase tracking-[0.08em] text-text-muted">
          Engineering
        </p>
        <h1 className="mt-2 text-fluid-hero text-text-primary min-w-0 overflow-wrap-anywhere">
          Production notes
        </h1>
        <p className="mt-4 text-base leading-relaxed text-text-secondary">
          Incidents from the worker that refreshes visa-sponsored European
          software jobs every six hours. Numbers from production. No runbooks.
        </p>
        <ol className="engineering-index mt-10">
          {ENGINEERING_POSTS.map((post) => (
            <li key={post.slug}>
              <article>
                <time dateTime={post.datePublished} className="engineering-index-date">
                  {formatPostDate(post.datePublished)}
                </time>
                <h2 className="font-display text-xl font-semibold text-text-primary">
                  <a href={engineeringPostPath(post.slug)}>{post.title}</a>
                </h2>
                <p className="mt-2 text-sm leading-relaxed text-text-secondary">
                  {post.metric}
                </p>
              </article>
            </li>
          ))}
        </ol>
      </main>
    </EngineeringShell>
  );
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { CantStartNewThreadPost } from "@/components/engineering/CantStartNewThreadPost";
import { EngineeringShell } from "@/components/engineering/EngineeringShell";
import {
  ENGINEERING_AUTHOR,
  ENGINEERING_POSTS,
  LOGO,
  OG_IMAGE,
  SITE,
  engineeringPostPath,
  formatPostDate,
  getEngineeringPost,
} from "@/lib/engineering-posts";

const POST_BODIES: Record<string, () => React.ReactNode> = {
  "cant-start-new-thread": CantStartNewThreadPost,
};

type PageProps = {
  params: Promise<{ slug: string }>;
};

export function generateStaticParams() {
  return ENGINEERING_POSTS.map((post) => ({ slug: post.slug }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { slug } = await params;
  const post = getEngineeringPost(slug);
  if (!post) {
    return { title: "Not found" };
  }
  const path = engineeringPostPath(post.slug);
  const url = `${SITE}${path}`;
  return {
    title: post.title,
    description: post.description,
    alternates: { canonical: path },
    openGraph: {
      title: `${post.title} | Relocation Jobs`,
      description: post.description,
      url,
      siteName: "Relocation Jobs",
      type: "article",
      publishedTime: post.datePublished,
      modifiedTime: post.dateModified,
      authors: [ENGINEERING_AUTHOR.name],
      images: [
        {
          url: OG_IMAGE,
          width: 1200,
          height: 630,
          alt: post.title,
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title: `${post.title} | Relocation Jobs`,
      description: post.description,
      images: [OG_IMAGE],
    },
  };
}

export default async function EngineeringPostPage({ params }: PageProps) {
  const { slug } = await params;
  const post = getEngineeringPost(slug);
  const Body = POST_BODIES[slug];
  if (!post || !Body) {
    notFound();
  }
  const path = engineeringPostPath(post.slug);
  const url = `${SITE}${path}`;
  const jsonLd = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "BlogPosting",
        headline: post.title,
        description: post.description,
        datePublished: post.datePublished,
        dateModified: post.dateModified,
        url,
        mainEntityOfPage: url,
        image: OG_IMAGE,
        author: {
          "@type": "Person",
          name: ENGINEERING_AUTHOR.name,
          url: ENGINEERING_AUTHOR.url,
        },
        publisher: {
          "@type": "Organization",
          name: "Relocation Jobs",
          alternateName: "KUCHUP",
          url: `${SITE}/`,
          logo: {
            "@type": "ImageObject",
            url: LOGO,
          },
        },
      },
      {
        "@type": "BreadcrumbList",
        itemListElement: [
          {
            "@type": "ListItem",
            position: 1,
            name: "Home",
            item: `${SITE}/`,
          },
          {
            "@type": "ListItem",
            position: 2,
            name: "Engineering",
            item: `${SITE}/engineering`,
          },
          {
            "@type": "ListItem",
            position: 3,
            name: post.title,
            item: url,
          },
        ],
      },
    ],
  };

  return (
    <EngineeringShell>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <main className="mx-auto mt-12 max-w-2xl">
        <nav aria-label="Breadcrumb" className="engineering-breadcrumb">
          <ol>
            <li>
              <a href="/engineering">Engineering</a>
            </li>
            <li aria-current="page">{post.title}</li>
          </ol>
        </nav>
        <header className="mt-6">
          <p className="text-sm font-medium uppercase tracking-[0.08em] text-text-muted">
            Production incident
          </p>
          <h1 className="mt-2 text-fluid-hero text-text-primary min-w-0 overflow-wrap-anywhere">
            {post.title}
          </h1>
          <p className="engineering-byline mt-4">
            <time dateTime={post.datePublished}>
              {formatPostDate(post.datePublished)}
            </time>
            <span aria-hidden="true"> · </span>
            <a href={ENGINEERING_AUTHOR.url}>{ENGINEERING_AUTHOR.name}</a>
          </p>
          <p className="mt-4 text-base leading-relaxed text-text-secondary">
            {post.metric}
          </p>
        </header>
        <article className="mt-10">
          <Body />
        </article>
        <p className="engineering-close mt-12">
          This worker is why the catalog of visa-sponsored software jobs
          refreshes about every six hours.{" "}
          <a href="/how-it-works">How Kuchup finds roles</a>
          {" · "}
          <a href="/engineering">More engineering notes</a>
        </p>
      </main>
    </EngineeringShell>
  );
}

